//! Report only. Fixture index must already exist; this binary never acquires or writes bytes.
use of1_range_recorder::{PersistedIndex, RangePlan, fixture, plan_ranges, validate_plan};
use std::{fmt::Write, path::Path};

fn markdown(plan: &RangePlan) -> String {
    let mut text = String::from(
        "# OF1 offline index-plan evidence\n\n> **Document status: ACTIVE — FIXTURE ONLY.** Generated by `of1-plan-evidence`; not an acquisition receipt.\n\nNo network or historical data. The source-format pin is not activation/authenticity evidence.\nCaller fingerprints in this fixture are labelled synthetic context, not runtime attestations.\n\n",
    );
    writeln!(text, "- Plan SHA-256: `{}`\n- Persisted fixture-index SHA-256: `{}`\n- Host identity (not contacted): `{}`\n- Object: `{}`\n- Index: `{}`\n", plan.plan_sha256, plan.index_sha256, plan.source_host, plan.source_path, plan.index_path).expect("string formatting");
    text.push_str("| Request | Index record | Slot | Byte start | Byte end (exclusive) |\n|---|---|---|---|---|\n");
    for r in &plan.requests {
        writeln!(
            text,
            "| {} | {} | {} | {} | {} |",
            r.sequence, r.index_record, r.slot, r.start, r.end_exclusive
        )
        .expect("string formatting");
    }
    writeln!(text, "\nPlanned payload response-entity bytes: {}. These are not measured received bytes.\n\nIndex-reported absent: `{:?}`; no on-chain skipped-slot proof.\n\nSlot semantics: `{}`. Epoch-root membership: `{}`. CID verification: `{}`.\n\nBlocks, transactions and Pump-event counts: `UNAVAILABLE_NOT_DECODED_IN_B4`.\n\nThis PR does not implement Raw publication, runtime budget enforcement, resume or HTTP.\nB4 remains In Progress / ACTIVE NOW / Unproven; B5 remains Backlog / NEXT / Unproven.\nNo acquisition run is authorized.\n", plan.planned_response_entity_bytes, plan.index_reported_absent, plan.slot_semantic_membership, plan.root_membership, plan.cid_verification).expect("string formatting");
    text.truncate(text.trim_end().len());
    text.push('\n');
    text
}

fn run() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<_> = std::env::args().skip(1).collect();
    if args.len() != 2 || !["--json", "--markdown"].contains(&args[0].as_str()) {
        return Err("usage: of1-plan-evidence --json|--markdown <persisted-fixture-index>".into());
    }
    let plan = validate_plan(fixture::plan())?;
    let index = PersistedIndex::read(&plan, Path::new(&args[1]))?;
    let ranges = plan_ranges(&plan, &index)?;
    if args[0] == "--json" {
        println!("{}", serde_json::to_string_pretty(&ranges)?);
    } else {
        print!("{}", markdown(&ranges));
    }
    Ok(())
}

fn main() {
    if let Err(error) = run() {
        eprintln!("{error}");
        std::process::exit(1);
    }
}
